window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9911a7f89504fbf4"]={"versions": [{"id": "FIG-9911a7f89504fbf4", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Zeitverhaltens im Rahmen des AUTOSAR System Templates. Das Metamodell definiert die strukturelle Beschreibung anfragegesteuerter Reaktionszeiten (<code>RequestControlledTiming</code>) auf Systemebene einschließlich Toleranzgrenzen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>RequestControlledTiming</code>: Hauptklasse mit dem Attribut <code>+ finalRepetitions: Int [0..1]</code>. Sie besitzt eine gerichtete Komposition via Rolle <code>+responseTime</code> mit der Multiplizität <code>1</code> auf <code>TimeRangeType</code>.</li>\n<li><code>TimeRangeType</code>: Repräsentiert das Zeitintervall mit dem Attribut <code>+ value: Float</code>. Besitzt eine gerichtete Komposition via Rolle <code>+tolerance</code> mit der Multiplizität <code>0..1</code> auf <code>TimeRangeTypeTolerance</code>.</li>\n<li><code>TimeRangeTypeTolerance</code>: Abstrakte Basisklasse (kursiv dargestellt) für Toleranzvorgaben.</li>\n<li><code>RelativeTolerance</code>: Spezialisierung von <code>TimeRangeTypeTolerance</code> (Generalisierungsbeziehung) mit dem Attribut <code>+ relative: Int</code>.</li>\n<li><code>AbsoluteTolerance</code>: Spezialisierung von <code>TimeRangeTypeTolerance</code> (Generalisierungsbeziehung) mit dem Attribut <code>+ absolute: Float</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdarstellung. Die Instanziierung modelliert ein Zeitfenster für anfragegesteuerte Aktionen: Ein <code>RequestControlledTiming</code>-Element erzwingt genau eine konkrete Antwortzeitvorgabe (<code>TimeRangeType</code>), für die optional maximal eine Toleranzspezifikation – entweder absolut als Fließkommawert oder relativ als Ganzzahl – deklariert werden kann.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungsartefakte im System Template müssen bei Verwendung von <code>RequestControlledTiming</code> genau ein <code>responseTime</code>-Element bereitstellen. Toleranzwerte sind polymorph über die Spezialisierungen von <code>TimeRangeTypeTolerance</code> zu instanziieren (<code>RelativeTolerance</code> oder <code>AbsoluteTolerance</code>). Für die Ganzzahlattribute <code>finalRepetitions</code> und <code>relative</code> ist der primitive Datentyp <code>Int</code> spezifiziert, für Zeit- und absolute Werte <code>Float</code>.</p>"}, {"id": "FIG-4ac1246506de63e8", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Zeitverhaltens im Rahmen des AUTOSAR System Templates. Das Metamodell definiert die strukturelle Beschreibung anfragegesteuerter Reaktionszeiten (<code>RequestControlledTiming</code>) auf Systemebene einschließlich Toleranzgrenzen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>RequestControlledTiming</code>: Hauptklasse mit dem Attribut <code>+ finalRepetitions :Integer [0..1]</code>. Sie besitzt eine gerichtete Komposition via Rolle <code>+responseTime</code> mit der Multiplizität <code>1</code> auf <code>TimeRangeType</code>.</li>\n<li><code>TimeRangeType</code>: Repräsentiert das Zeitintervall mit dem Attribut <code>+ value :Float</code>. Besitzt eine gerichtete Komposition via Rolle <code>+tolerance</code> mit der Multiplizität <code>0..1</code> auf <code>TimeRangeTypeTolerance</code>.</li>\n<li><code>TimeRangeTypeTolerance</code>: Abstrakte Basisklasse (kursiv dargestellt) für Toleranzvorgaben.</li>\n<li><code>RelativeTolerance</code>: Spezialisierung von <code>TimeRangeTypeTolerance</code> (Generalisierungsbeziehung) mit dem Attribut <code>+ relative :Integer</code>.</li>\n<li><code>AbsoluteTolerance</code>: Spezialisierung von <code>TimeRangeTypeTolerance</code> (Generalisierungsbeziehung) mit dem Attribut <code>+ absolute :Float</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdarstellung. Die Instanziierung modelliert ein Zeitfenster für anfragegesteuerte Aktionen: Ein <code>RequestControlledTiming</code>-Element erzwingt genau eine konkrete Antwortzeitvorgabe (<code>TimeRangeType</code>), für die optional maximal eine Toleranzspezifikation – entweder absolut als Fließkommawert oder relativ als Ganzzahl – deklariert werden kann.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungsartefakte im System Template müssen bei Verwendung von <code>RequestControlledTiming</code> genau ein <code>responseTime</code>-Element bereitstellen. Toleranzwerte sind polymorph über die Spezialisierungen von <code>TimeRangeTypeTolerance</code> zu instanziieren (<code>RelativeTolerance</code> oder <code>AbsoluteTolerance</code>). Für die Ganzzahlattribute <code>finalRepetitions</code> und <code>relative</code> ist der AUTOSAR-Primitivtyp <code>Integer</code> spezifiziert, für Zeit- und absolute Werte <code>Float</code>.</p>"}], "trans": [{"from": "FIG-9911a7f89504fbf4", "to": "FIG-4ac1246506de63e8", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Datentyp des Attributs <code>finalRepetitions</code> in Klasse <code>RequestControlledTiming</code>: Typisierung von <code>Int</code> zu <code>Integer</code> geändert.</li>\n<li>Datentyp des Attributs <code>relative</code> in Klasse <code>RelativeTolerance</code>: Typisierung von <code>Int</code> zu <code>Integer</code> geändert.</li>\n</ul>"}]};
